 IntPtr Hook(IntPtr h,int msg,IntPtr w,IntPtr l,ref bool handled){if(gameInputLocked&&msg==0x84){handled=true;return new IntPtr(-1);}IntPtr result;if(HandleMiniResize(msg,w,l,out result)){handled=true;return result;}if(msg==0x312){if(w.ToInt32()==17){Safe(Toggle);handled=true;}else if(w.ToInt32()==18){Safe(ToggleGameInput);handled=true;}else if(w.ToInt32()==19){Safe(OpenQuickNote);handled=true;}}return IntPtr.Zero;}
