 void ApplyWallpaper(){wallpaper.Source=null;wallpaper.Opacity=data.WallpaperOpacity;if(String.IsNullOrWhiteSpace(data.Wallpaper))return;try{var f=Path.GetFullPath(Path.Combine(Folder,data.Wallpaper));if(!f.StartsWith(Path.GetFullPath(Folder)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))return;wallpaper.Source=ReadWallpaperBitmap(f);}catch{Say("Не удалось загрузить фон. Выбери изображение заново.");}}
