 BitmapImage ReadWallpaperBitmap(string file){var bmp=new BitmapImage();using(var stream=File.OpenRead(file)){bmp.BeginInit();bmp.CacheOption=BitmapCacheOption.OnLoad;bmp.StreamSource=stream;bmp.DecodePixelWidth=1000;bmp.EndInit();}bmp.Freeze();return bmp;}
 void SetWallpaperFromFile(string file){var f=new FileInfo(file);if(f.Length>20*1024*1024)throw new Exception("Выбери изображение размером до 20 МБ.");ReadWallpaperBitmap(f.FullName);Directory.CreateDirectory(Folder);var name="wallpaper"+f.Extension.ToLowerInvariant();var dest=Path.Combine(Folder,name);if(!String.Equals(f.FullName,dest,StringComparison.OrdinalIgnoreCase))File.Copy(f.FullName,dest,true);data.Wallpaper=name;ApplyWallpaper();Save();Say("Твой фон установлен.");}
