 void RenderGoal(){RenderSavingsGoals();}
 void SummaryLegacy(){if(summary==null)return;var net=data.Entries.Where(t=>t.Date.Date==DateTime.Today).Sum(t=>t.Income?t.Amount:-t.Amount);summary.Text="Дела "+data.Tasks.Count(t=>t.Done)+"/"+data.Tasks.Count+"    ·    За сегодня "+(net<0?"− ":"")+Cash(Math.Abs(net));}
 void CasinoTab(){var p=Stack();p.Children.Add(Text("Итог казино",17));p.Children.Add(Text("Ручной учёт игровых денег. Записывай раунд или целую сессию - каждый результат только один раз.",11,"Muted"));casinoSummary=Text("",14,"Accent");p.Children.Add(Card(casinoSummary));p.Children.Add(Text("Активность",11,"Muted"));activity=new ComboBox{IsEditable=true,Text="Кости",Margin=new Thickness(0,0,0,12),Padding=new Thickness(8),MaxDropDownHeight=160};foreach(var s in new[]{"Кости","Рулетка","Блэкджек","Слоты","Другое"})activity.Items.Add(s);p.Children.Add(activity);p.Children.Add(Text("Всего поставил за раунд / сессию, $",11,"Muted"));stake=Input("Сумма ставок","0");p.Children.Add(stake);p.Children.Add(Text("Всего получил обратно (включая ставку), $",11,"Muted"));returned=Input("Сумма возвратов","0");p.Children.Add(returned);p.Children.Add(Text("Поставил 1 000, вернулось 1 800 → итог +800. Всё проиграл → возврат 0. Учёт ставок не смешивай с пополнением баланса казино.",11,"Muted"));p.Children.Add(Btn("Записать результат",()=>Safe(()=>{var s=Number(stake,false);var r=Number(returned,false);var game=activity.Text.Trim();if(s==0&&r==0)throw new Exception("Укажи ставку или возврат больше нуля.");if(game.Length==0||game.Length>80)throw new Exception("Укажи название активности (до 80 символов).");data.Casino.Add(new CasinoEntry{Id=Guid.NewGuid().ToString(),Activity=game,Stake=s,Returned=r,Date=DateTime.Now});Save();RenderCasino();stake.Text="0";returned.Text="0";Say("Результат записан. Итог = возвраты минус ставки.");}),true));p.Children.Add(Text("История и итог по активностям",15));casinoLedger=Stack();p.Children.Add(casinoLedger);Tab("Казино",p);}
 string Signed(double n){return (n>0?"+ ":n<0?"− ":"")+Cash(Math.Abs(n));}
 void RenderCasino(){if(data.Casino==null)data.Casino=new List<CasinoEntry>();casinoLedger.Children.Clear();double s=data.Casino.Sum(t=>t.Stake),r=data.Casino.Sum(t=>t.Returned);casinoSummary.Text="Поставлено: "+Cash(s)+"\nВернулось: "+Cash(r)+"\nОбщий итог: "+Signed(r-s);foreach(var g in data.Casino.GroupBy(t=>t.Activity))casinoLedger.Children.Add(Text(g.Key+": "+Signed(g.Sum(t=>t.Returned-t.Stake)),12,"Accent"));if(data.Casino.Count==0)casinoLedger.Children.Add(Text("Записей пока нет. Итог считается только по внесённым данным.",12,"Muted"));foreach(var t in data.Casino.AsEnumerable().Reverse().Take(100)){var p=new DockPanel();var del=Btn("×",()=>{data.Casino.Remove(t);Save();RenderCasino();});DockPanel.SetDock(del,Dock.Right);p.Children.Add(del);var info=Stack();info.Children.Add(Text(t.Activity+" · "+Signed(t.Returned-t.Stake),14));info.Children.Add(Text("Ставки "+Cash(t.Stake)+" → возвраты "+Cash(t.Returned),11,"Muted"));info.Children.Add(Text(t.Date.ToString("dd.MM HH:mm"),10,"Muted"));p.Children.Add(info);casinoLedger.Children.Add(Card(p));}}
 void RenderAll(){ApplySectionOrder();ApplyGameOrder();RenderTasks();RenderTimers();RenderLedger();RenderGoal();RenderNotes();TickMini();}
 void Tick(){TrackExternalWindow();if(showEvent!=null&&showEvent.WaitOne(0))Reveal();var expired=new List<string>();foreach(var t in data.Timers){var left=Left(t);if(clocks.ContainsKey(t.Id))clocks[t.Id].Text=left<=0?"Готово":Clock(left);if(toggles.ContainsKey(t.Id))toggles[t.Id].Content=left<=0?"ЕЩЁ РАЗ":t.End==0?"ПРОДОЛЖИТЬ":"ПАУЗА";if(left<=0&&t.End>0&&!t.Alerted){t.Alerted=true;expired.Add(t.Title);}}if(expired.Count>0){Save();Notify(String.Join("\n",expired));}if(notice!=null&&Now>noticeUntil){notice.Close();notice=null;}Summary();UpdateTimerVisuals();TickMini();TickWidgets();SyncMiniDock();}
 void Notify(string message){if(data.Sound)System.Media.SystemSounds.Exclamation.Play();if(tray!=null)tray.ShowBalloonTip(8000,"Таймер завершён",message.Length>230?message.Substring(0,230):message,Forms.ToolTipIcon.Info);if(notice!=null)notice.Close();notice=new Window{Title="Majestic · Таймер завершён",Width=345,SizeToContent=SizeToContent.Height,WindowStyle=WindowStyle.None,AllowsTransparency=true,Background=Brush("#00000000"),Topmost=true,ShowInTaskbar=false,ShowActivated=false,ResizeMode=ResizeMode.NoResize};var p=new StackPanel();var title=new TextBlock{Text=data.Theme=="cute"?"♡  Время вышло":"M↗  Время вышло",Foreground=(Brush)Resources["Accent"],FontSize=17,FontWeight=FontWeights.Bold,Margin=new Thickness(0,0,0,10)};p.Children.Add(title);p.Children.Add(new TextBlock{Text=message,TextWrapping=TextWrapping.Wrap,Foreground=Brush("#FFFFFF"),FontSize=14,Margin=new Thickness(0,0,0,12)});var close=new Button{Content="Понятно",Padding=new Thickness(10,7,10,7),Background=(Brush)Resources["Accent"],Foreground=(Brush)Resources["AccentText"]};close.Click+=(s,e)=>{if(notice!=null){notice.Close();notice=null;}};p.Children.Add(close);notice.Content=new Border{Background=Brush(data.Theme=="cute"?"#F5423045":"#F51C252A"),BorderBrush=(Brush)Resources["Accent"],BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(14),Padding=new Thickness(20),Child=p};notice.Left=SystemParameters.WorkArea.Right-365;notice.Top=SystemParameters.WorkArea.Bottom-230;noticeUntil=Now+12000;noticeInputGate=new CompanionInputGate(notice);noticeInputGate.Locked=gameInputLocked;notice.Show();}
 static void Log(string text){try{File.AppendAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"startup.log"),DateTime.Now.ToString("HH:mm:ss ")+text+Environment.NewLine);}catch{}}
 [STAThread] public static void Main(string[] args){RunWithSplash();}
